(5449197, 784383, 101256, '<td valign="top">Beer - the food of champions. Very good although this is something that the mules that hang around the barn get as a treat - can''t really rate this as "Not Qute Right" even if it is an uncommon practice. However, it can be viewed as not quite right and given that this is a beautiful image of the trust between a horse and owner, it clearly is a cut above some of the other images in this challenge. Well done.</td>', 'Beer - the food of champions. Very good although this is something that the mules that hang around the barn get as a treat - can''t really rate this as "Not Qute Right" even if it is an uncommon practice. However, it can be viewed as not quite right and given that this is a beautiful image of the trust between a horse and owner, it clearly is a cut above some of the other images in this challenge. Well done.', '2009-04-22 20:29:41.000000', NULL, 1),
(5449200, 784413, 101256, '<td valign="top">And perfectly Not Quite Right. Very different and very unique - definetly meets the challenge criteria. Well done.</td>', 'And perfectly Not Quite Right. Very different and very unique - definetly meets the challenge criteria. Well done.', '2009-04-22 20:30:48.000000', NULL, 1),
(5449203, 783763, 101256, '<td valign="top">This is definetly Not Quite Right - a good eye and a good capture - well done all around in meeting the challenge criteria and creating a sound and solid image. Well done.</td>', 'This is definetly Not Quite Right - a good eye and a good capture - well done all around in meeting the challenge criteria and creating a sound and solid image. Well done.', '2009-04-22 20:33:17.000000', NULL, 1),
(5449204, 784186, 106148, '<td valign="top">Well.....i mean if a person''s been around, who knows what they might catch.<br/>Nice DOP.</td>', 'Well.....i mean if a person''s been around, who knows what they might catch.Nice DOP.', '2009-04-22 20:34:12.000000', NULL, 1),
(5449206, 783742, 106148, '<td valign="top">Beautiful. Love the colors and lighting...just love it. Lol, well done.</td>', 'Beautiful. Love the colors and lighting...just love it. Lol, well done.', '2009-04-22 20:35:50.000000', NULL, 1),
(5449207, 784264, 101256, '<td valign="top">Very clever and humorous, this image meets the challenge criteria perfectly as being Not Quite Right. From that standpoint, it is the most unique image so far in the challenge. From an image standpoint, it is technically flawed by being over sharpened which gives the image an unnatural appearance. Having said that, the whimsical nature of the image compared to it''s minor technical flaw is over whelming. Well done.</td>', 'Very clever and humorous, this image meets the challenge criteria perfectly as being Not Quite Right. From that standpoint, it is the most unique image so far in the challenge. From an image standpoint, it is technically flawed by being over sharpened which gives the image an unnatural appearance. Having said that, the whimsical nature of the image compared to it''s minor technical flaw is over whelming. Well done.', '2009-04-22 20:36:34.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5449211, 784443, 101256, '<td valign="top">An excellant capture and the title gives the image some purpose and clarity. The image itself is properly lit and well composed. A good solid entry into the challenge.</td>', 'An excellant capture and the title gives the image some purpose and clarity. The image itself is properly lit and well composed. A good solid entry into the challenge.', '2009-04-22 20:38:44.000000', NULL, 1),
(5449212, 783388, 35602, '<td valign="top">Interesting take on the challenge.  Could have been great with a bit more brightness and less grain.</td>', 'Interesting take on the challenge.  Could have been great with a bit more brightness and less grain.', '2009-04-22 20:39:51.000000', NULL, 1),
(5449213, 784395, 101256, '<td valign="top">Clever title and a crisp sharp image meets the challenge criteria in a unique way. A good solid effort.</td>', 'Clever title and a crisp sharp image meets the challenge criteria in a unique way. A good solid effort.', '2009-04-22 20:40:03.000000', NULL, 1),
(5449217, 783844, 106148, '<td valign="top">Neat. Although maybe an angle from the base of the mug looking up? And more centralized smoke coming just from the cup alone. But I''m being picky. Interesting spin on hot coffee.</td>', 'Neat. Although maybe an angle from the base of the mug looking up? And more centralized smoke coming just from the cup alone. But I''m being picky. Interesting spin on hot coffee.', '2009-04-22 20:41:06.000000', NULL, 1),
(5449218, 782860, 35602, '<td valign="top">Nice texture.  A bit soft on focus and subject needs a bit more zip.</td>', 'Nice texture.  A bit soft on focus and subject needs a bit more zip.', '2009-04-22 20:41:37.000000', NULL, 1),
(5449219, 782922, 35602, '<td valign="top">Very creative.</td>', 'Very creative.', '2009-04-22 20:42:09.000000', NULL, 1),
(5449221, 784312, 101256, '<td valign="top">Laugh out loud funny, this entry meets the challenge criteria in fine fashion and demonstrates a clever use of title and subject matter. A top ten image and a very strong ribbon contender. Well done.</td>', 'Laugh out loud funny, this entry meets the challenge criteria in fine fashion and demonstrates a clever use of title and subject matter. A top ten image and a very strong ribbon contender. Well done.', '2009-04-22 20:42:29.000000', NULL, 1),
(5449222, 784434, 106148, '<td valign="top">Yeah, definitely in or from the Matrix, lol.</td>', 'Yeah, definitely in or from the Matrix, lol.', '2009-04-22 20:42:31.000000', NULL, 1),
(5449223, 784305, 35602, '<td valign="top">Great juxtoposition here.  Nice detail and lighting.  9</td>', 'Great juxtoposition here.  Nice detail and lighting.  9', '2009-04-22 20:42:50.000000', NULL, 1),
(5449231, 784377, 35602, '<td valign="top">Hmmm.  Not a strong subject.  Just seems a bit too overexposed in the foam of the water.  Compositionally, I think the fence on the right seems to make a very unbalanced image.  Just a lot of issues and imho not any strengths I can grab onto</td>', 'Hmmm.  Not a strong subject.  Just seems a bit too overexposed in the foam of the water.  Compositionally, I think the fence on the right seems to make a very unbalanced image.  Just a lot of issues and imho not any strengths I can grab onto', '2009-04-22 20:45:27.000000', NULL, 1),
(5449232, 783993, 101256, '<td valign="top">A combination of set piece imagery matching the title, it is the very epitome of the classic scifi/horror/fantasy genre movie and as such demonstrates a proper interpretation of Not Quite Right. A good solid entry into the challenge, it should place well in the top twenty if not top ten. Well done.</td>', 'A combination of set piece imagery matching the title, it is the very epitome of the classic scifi/horror/fantasy genre movie and as such demonstrates a proper interpretation of Not Quite Right. A good solid entry into the challenge, it should place well in the top twenty if not top ten. Well done.', '2009-04-22 20:45:30.000000', NULL, 1),
(5449234, 784442, 35602, '<td valign="top">Pretty</td>', 'Pretty', '2009-04-22 20:45:59.000000', NULL, 1),
(5449238, 784311, 101256, '<td valign="top">A good interpretation of Not Quite Right, the unlevel level is a perfect demonstration of the challenge criteria. The little fine details are a plus. <br/>Well done.</td>', 'A good interpretation of Not Quite Right, the unlevel level is a perfect demonstration of the challenge criteria. The little fine details are a plus. Well done.', '2009-04-22 20:47:56.000000', NULL, 1),
(5449241, 784186, 101256, '<td valign="top">and thus are Not Quite Right. Very clever presentation and matches the challenge criteria in a unique and clever way. Well done.</td>', 'and thus are Not Quite Right. Very clever presentation and matches the challenge criteria in a unique and clever way. Well done.', '2009-04-22 20:48:54.000000', NULL, 1),
(5449242, 783865, 35602, '<td valign="top">Definitely not quite right.  Bet she is a real sweetheart.</td>', 'Definitely not quite right.  Bet she is a real sweetheart.', '2009-04-22 20:49:20.000000', NULL, 1),
(5449245, 783123, 35602, '<td valign="top">Nice contrast and tone.  LOve the way the light enhances the flow of the sculpture.</td>', 'Nice contrast and tone.  LOve the way the light enhances the flow of the sculpture.', '2009-04-22 20:50:12.000000', NULL, 1),
