(5449259, 784398, 106148, '<td valign="top">Love the contrast... Very nice.</td>', 'Love the contrast... Very nice.', '2009-04-22 20:58:31.000000', NULL, 1),
(5449263, 784242, 106148, '<td valign="top">Awwwww.</td>', 'Awwwww.', '2009-04-22 21:00:37.000000', NULL, 1),
