(5455073, 784073, 96751, '<td valign="top">Great colors and clarity.</td>', 'Great colors and clarity.', '2009-04-28 01:04:10.000000', NULL, 1),
(5455077, 784305, 96751, '<td valign="top">I love the guy and the tea party.  It is so odd, so quirky, so sweet.  Great treatment, although it looks like the conduit portion is from another shot.  I hope this is legal, ''cause I really like it.</td>', 'I love the guy and the tea party.  It is so odd, so quirky, so sweet.  Great treatment, although it looks like the conduit portion is from another shot.  I hope this is legal, ''cause I really like it.', '2009-04-28 01:05:44.000000', NULL, 1),
(5455079, 784447, 96751, '<td valign="top">Must be really spicy...</td>', 'Must be really spicy...', '2009-04-28 01:05:56.000000', NULL, 1),
(5455080, 783556, 96751, '<td valign="top">Very interesting.  I like the tilt, but the back lighting doesn''t help the subject.  And the harsh shadow is also distracting.  I wonder what it might have looked like from the other side.</td>', 'Very interesting.  I like the tilt, but the back lighting doesn''t help the subject.  And the harsh shadow is also distracting.  I wonder what it might have looked like from the other side.', '2009-04-28 01:06:43.000000', NULL, 1),
